    internal static bool TryAcquire(ShimRoot root, out ShimAreas? areas, out string why)
    {
        var taken = new ShimAreas(root, out why);
        areas = why.Length == 0 ? taken : null;
        return areas is not null;
    }

    internal static int Count => 22;
